<template>
    <component v-if="!asChild" :is="as" :class="cx('root')" :type="as === 'BUTTON' || as === 'button' ? 'button' : undefined" v-bind="attrs">
        <slot />
    </component>
    <slot v-else :a11yAttrs="a11yAttrs" :class="cx('root')" />
</template>

<script>
import { mergeProps } from 'vue';
import BaseSidebarGroupAction from './BaseSidebarGroupAction.vue';

export default {
    name: 'SidebarGroupAction',
    extends: BaseSidebarGroupAction,
    inheritAttrs: false,
    computed: {
        a11yAttrs() {
            return {
                'data-pc-name': 'sidebargroupaction',
                'data-pc-section': 'root'
            };
        },
        attrs() {
            return mergeProps(this.a11yAttrs, this.ptmi('root'));
        }
    }
};
</script>
